def count_inversions(nums):
    def sort(a):
        if len(a) <= 1:
            return a, 0
        mid = len(a) // 2
        l, x = sort(a[:mid])
        r, y = sort(a[mid:])
        out, i, j, c = [], 0, 0, x + y
        while i < len(l) and j < len(r):
            if l[i] <= r[j]:
                out.append(l[i]); i += 1
            else:
                out.append(r[j]); j += 1
                c += len(l) - i
        return out + l[i:] + r[j:], c
    return sort(nums)[1]
